---------------------------------------------------------------------
-- Default tables: seeded ONCE into a fresh database from server/default_data.lua
-- (generated by tools/export-gambling-defaults.py), per Config.DefaultTables.Groups.
-- A marker row in grumpy_gambling_meta stops it ever running again, so tables an admin
-- deletes later stay deleted. A database that already has tables is only marked.
-- Registered before Tables.Load (fxmanifest order), so the seeded tables load the same start.
---------------------------------------------------------------------
local MARK = 'default_tables_seeded'

GG.AfterLoad(function()
    local cfg = Config.DefaultTables
    if not (cfg and cfg.Enabled) or not GG.DefaultData then return end
    if MySQL.scalar.await('SELECT v FROM grumpy_gambling_meta WHERE k = ?', { MARK }) then return end

    local function mark(note)
        MySQL.insert.await('INSERT IGNORE INTO grumpy_gambling_meta (k, v) VALUES (?, ?)', { MARK, note })
    end
    if (MySQL.scalar.await('SELECT COUNT(*) FROM grumpy_gambling_tables') or 0) > 0 then
        return mark('skipped: tables already placed')
    end

    for _, m in ipairs(GG.DefaultData.models or {}) do
        if Models[m.model] then
            MySQL.insert.await('INSERT IGNORE INTO grumpy_gambling_models (model, data, updated_by) VALUES (?, ?, ?)',
                { m.model, m.data, 'defaults' })
        end
    end

    local seeded, groups = 0, cfg.Groups or {}
    for _, t in ipairs(GG.DefaultData.tables or {}) do
        if groups[t.group] and Models[t.model] then
            MySQL.insert.await([[INSERT INTO grumpy_gambling_tables
                (label, kind, source, model, bound, x, y, z, h, currency, fixed_tier, seats, dealer, settings, enabled, created_by)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)]], {
                t.label, t.kind, t.source or 'public', t.model, t.bound or 0, t.x, t.y, t.z, t.h or 0.0,
                t.currency or 'cash', t.fixed_tier, t.seats, t.dealer, t.settings, t.enabled or 1, 'defaults',
            })
            seeded = seeded + 1
        end
    end
    mark(('seeded %d tables'):format(seeded))
    print(('^2[grumpy-gambling] seeded %d default tables^7'):format(seeded))
end)
